import {VaultScene} from './scene.js';
import {CASES,circularDistance,proximity,matchesPin,matchesFrequency,rating} from './puzzles.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const ICONS={headphones:'M3 14v-3a9 9 0 0 1 18 0v3M3 13h4v8H5a2 2 0 0 1-2-2zm18 0h-4v8h2a2 2 0 0 0 2-2z',volume:'M11 4 6 8H2v8h4l5 4zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',muted:'M11 4 6 8H2v8h4l5 4zM16 9l6 6m0-6-6 6',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0', 'chevron-down':'m6 9 6 6 6-6','chevron-right':'m9 5 7 7-7 7',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 12h8m-4-4v8',tap:'m14 3 7 7-4 4-7-7zM12 9 3 18v3h3l9-9M4 4l2 2m-3 4h3m4-7v3',rotate:'M3 11a9 9 0 1 1 2 7M3 4v7h7',mouse:'M7 3h10a2 2 0 0 1 2 2v10a7 7 0 0 1-14 0V5a2 2 0 0 1 2-2zm5 0v7',wave:'M2 12h3l2-7 4 14 4-14 3 7h4',info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',notebook:'M6 3h14v18H6zM3 6h5M3 10h5M3 14h5M3 18h5m4-11h5m-5 4h5',bulb:'M9 18h6m-6 3h6M8 15a7 7 0 1 1 8 0l-1 3H9z',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',unlock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0m-4 9v2',close:'m6 6 12 12m0-12L6 18',check:'m5 12 4 4L20 5',play:'m7 3 14 9-14 9z',pause:'M7 4h3v16H7zm7 0h3v16h-3z'};
function icons(root=document){root.querySelectorAll('i[data-icon]').forEach(i=>{i.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[i.dataset.icon]||ICONS.wave}"/></svg>`;});}icons();
const KEY='resonance-vault-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{};
const cleanRun=()=>({phase:0,pins:0,angle:0,frequency:300,seconds:0,mistakes:0,hints:0,clues:[],complete:false,started:false});
let caseIndex=Number.isInteger(saved.caseIndex)&&saved.caseIndex>=0&&saved.caseIndex<3?saved.caseIndex:0;
let runs=CASES.map((_,i)=>{const r=saved.runs?.[i];return r&&Number.isInteger(r.phase)&&r.phase>=0&&r.phase<=3&&Number.isInteger(r.pins)&&r.pins>=0&&r.pins<=3&&Array.isArray(r.clues)?{...cleanRun(),...r}:cleanRun();});
let settings={visualAssist:true,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,muted:false,...saved.settings};let listening=false,filter='raw',gain=.65,tool='listen',patternInput=[],patternPlaying=false,playToken=0,caseEpoch=0,toastTimer,scene,signal=0,lastTick=0;
const run=()=>runs[caseIndex],current=()=>CASES[caseIndex];
function save(){try{localStorage.setItem(KEY,JSON.stringify({caseIndex,runs,settings}));}catch{}}
function feedback(message,type=''){const el=$('#feedback');el.className='feedback-line '+type;el.innerHTML='<span class="feedback-dot"></span>';el.append(document.createTextNode(message));}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
const time=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;
class AudioEngine{
 constructor(){this.ctx=null;this.nodes=[];this.oscillators=[];this.lastTone=0;}
 async init(){try{if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=settings.muted?0:gain*.38;this.analyser=this.ctx.createAnalyser();this.analyser.fftSize=1024;this.master.connect(this.analyser);this.analyser.connect(this.ctx.destination);this.data=new Uint8Array(this.analyser.fftSize);}if(this.ctx.state==='suspended')await this.ctx.resume();return true;}catch{toast('当前浏览器无法播放声音，可以开启视觉辅助继续调查。');return false;}}
 volume(){if(this.ctx)this.master.gain.setTargetAtTime(settings.muted?0:gain*.38,this.ctx.currentTime,.05);}
 tone(freq,duration=.18,type='sine',level=.3,delay=0){if(!this.ctx||this.ctx.state!=='running')return;const t=this.ctx.currentTime+delay;const o=this.ctx.createOscillator(),v=this.ctx.createGain();o.type=type;o.frequency.value=freq;v.gain.setValueAtTime(0,t);v.gain.linearRampToValueAtTime(level,t+.008);v.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(v);v.connect(this.master);o.start(t);o.stop(t+duration+.02);o.onended=()=>{o.disconnect();v.disconnect();};}
 click(strength,aligned=false){if(!this.ctx)return;const f=filter==='low'?370:filter==='high'?1900:1040;this.tone(f+strength*700,.055,'triangle',.13+strength*.21);if(strength>.45)this.tone(f+strength*700,.055,'triangle',.15+strength*.18,.10);if(aligned)this.tone(660,.20,'sine',.13,.14);}
 knock(){this.tone(95,.4,'triangle',.6);this.tone(176,.23,'sine',.2,.07);}
 success(){[440,554.37,659.25].forEach((f,i)=>this.tone(f,.5,'sine',.25,i*.1));}
 error(){this.tone(180,.18,'triangle',.23);this.tone(140,.25,'sine',.18,.12);}
 resonance(){this.stopResonance();if(!this.ctx||!listening||run().phase!==1)return;[current().frequency,run().frequency].forEach((f,i)=>{const o=this.ctx.createOscillator(),v=this.ctx.createGain();o.frequency.value=f;o.type='sine';v.gain.value=.14;o.connect(v);v.connect(this.master);o.start();this.oscillators.push(o);this.nodes.push(v);});}
 updateResonance(){if(this.oscillators[1])this.oscillators[1].frequency.setTargetAtTime(run().frequency,this.ctx.currentTime,.025);}
 stopResonance(){this.oscillators.forEach(o=>{o.stop();o.disconnect();});this.nodes.forEach(n=>n.disconnect());this.oscillators=[];this.nodes=[];}
}
const audio=new AudioEngine();
try{scene=new VaultScene($('#scene'),value=>setTuning(value),action=>{if(action==='knock')knock();else if(action==='inspect')inspect();else if(!listening)toggleListening();});scene.setCase(caseIndex);scene.lowMotion=settings.reducedMotion;scene.resetView();}catch(e){console.warn('3D rendering unavailable',e);$('#scene').innerHTML='<div class="webgl-error"><strong>声学工作台已就绪</strong><p>此设备暂时无法显示 3D 场景。你仍可使用下方锁盘、声音分析仪与视觉辅助完成所有调查。</p></div>';}
function syncScene(){scene?.setState({angle:run().angle,phase:run().phase,pins:run().pins,listening,signal,complete:run().complete});}
function addClue(title,detail){run().clues.push({title,detail});renderNotes();}
function renderNotes(){const clues=run().clues;$('#clueCount').textContent=`${String(clues.length).padStart(2,'0')} / 03`;$('#notes').innerHTML=clues.length?clues.map((n,i)=>`<div class="note"><span>0${i+1}</span><p>${n.title}<small>${n.detail}</small></p></div>`).join(''):'<div class="empty-note"><span>01</span><p>转动锁盘，寻找清脆的双击声。<small>声音越清晰，距离正确位置越近。</small></p></div>';$('#hintCost').textContent=`${Math.max(0,3-run().hints)} 次可用`;$('#hintButton').disabled=run().hints>=3||run().complete;}
function render(){const r=run(),c=current();$('#caseName').textContent=c.name;$('#caseDescription').textContent=c.description;$('#caseBadge').textContent=`档案 № 00${caseIndex+1}`;$('#objectLabel').textContent=`${c.model} / MODEL 0${caseIndex+1}`;$('.scene-case-number').innerHTML=`0${caseIndex+1}<span>/ 03</span>`;$('.scene-caption small').textContent=`EST. ${c.year}`;$('#timer').textContent=time(r.seconds);$('#overallProgress').textContent=`${r.phase} / 3 已完成`;$$('.phase').forEach((el,i)=>{el.classList.toggle('active',i===r.phase);el.classList.toggle('done',i<r.phase);el.querySelector('.phase-number').textContent=i<r.phase?'✓':`0${i+1}`;});$('#pinProgress').innerHTML=[0,1,2].map(i=>`<b class="${i<r.pins?'done':''}"></b>`).join('');const rhythm=r.phase===2;$('.slider-controls').hidden=rhythm;$('.slider-controls').style.display=rhythm?'none':'flex';$('.slider-labels').style.display=rhythm?'none':'flex';$('#rhythmControls').hidden=!rhythm;$('#tuning').disabled=r.complete;$('#stepDown').disabled=r.complete;$('#stepUp').disabled=r.complete;$('#confirmButton').disabled=r.complete;$('#controlLabel').textContent=r.phase===0?'锁盘角度':r.phase===1?'共振频率':r.complete?'调查完成':'旋律复现';$('#controlValue').innerHTML=r.phase===0?`${String(r.angle).padStart(3,'0')}<small>°</small>`:r.phase===1?`${r.frequency}<small>Hz</small>`:r.complete?'003<small>/03</small>':`${patternInput.length}<small>/${c.pattern.length}</small>`;$('#tuning').setAttribute('aria-label',r.phase===0?'锁盘角度':'共振频率');$('#tuning').min=r.phase===0?0:200;$('#tuning').max=r.phase===0?359:800;$('#tuning').value=r.phase===0?r.angle:r.frequency;$('#tuning').style.setProperty('--value',`${r.phase===0?r.angle/359*100:(r.frequency-200)/6}%`);$('#rangeMin').textContent=r.phase===0?'0°':'200 Hz';$('#rangeMax').textContent=r.phase===0?'359°':'800 Hz';$('#tuningInstruction').textContent=r.phase===0?'缓慢转动，捕捉锁芯反馈':'调节频率，让两个声音归于平静';$('#confirmButton span').textContent=r.phase===0?'确认落点':r.phase===1?'锁定共振':r.complete?'已解密':'重新演奏';$('#confirmButton i').dataset.icon=r.complete?'unlock':r.phase===2?'rotate':'lock';icons($('#confirmButton'));$('#scopeFreq').textContent=r.phase===0?'LOCK FREQUENCY':r.phase===1?'RESONANCE FREQUENCY':'MEMORY ECHO';$('#noteIntro').textContent=r.complete?'这段被封存的回响，终于被你听见。':r.phase===0?'安静下来。每一枚锁芯，都有自己的声音。':r.phase===1?'两个声音越接近，起伏的拍频越慢。':'先听完整旋律，再用低、中、高音复现它。';$('#listenButton').disabled=r.complete;$('#mobileListen').hidden=r.complete;$('#returnReport').hidden=true;$('#unlockOverlay').hidden=!r.complete;if(r.complete){$('#successStory').textContent=c.story;$('#resultRank').textContent=rating(r.mistakes,r.hints);$('#resultTime').textContent=time(r.seconds);$('#resultClues').textContent=`${r.clues.length} / 3`;$('#nextCase').innerHTML=caseIndex<2?'调查下一件藏品 <i data-icon="chevron-right"></i>':'查看全部档案 <i data-icon="notebook"></i>';icons($('#nextCase'));}renderNotes();updateSignal();syncScene();save();}
function updateSignal(){const r=run(),c=current();signal=r.phase===0?proximity(r.angle,c.pins[Math.min(r.pins,2)],80,true):r.phase===1?proximity(r.frequency,c.frequency,140):.65;$('#signalDb').textContent=listening?`${Math.round(-46+signal*32+gain*8)} dB`:'−∞ dB';$('#signalDot').classList.toggle('active',listening);$('#signalState').textContent=listening?'正在采样':'等待接入';$('#annotationTitle').textContent=r.phase===0?'黄铜共振锁芯':r.phase===1?'异常共振薄膜':'声学记忆核心';let detail='等待声学采样';if(listening){if(!settings.visualAssist)detail='专注聆听锁芯反馈';else if(r.phase===0){const d=circularDistance(r.angle,c.pins[Math.min(r.pins,2)]);detail=d<=c.tolerance?'清脆双击 · 可以确认':d<20?'双击渐清 · 已经很近':d<65?'出现余响 · 继续细调':'沉闷单击 · 缓慢探索';}else if(r.phase===1){const d=Math.abs(r.frequency-c.frequency);detail=d<=c.freqTolerance?'波形稳定 · 可以共振':d<30?'拍频减慢 · 继续微调':'拍频急促 · 继续调节';}else detail='记住音高的顺序';}$('#annotationSub').textContent=detail;$('.scope').classList.toggle('frequency-match',listening&&signal>.94);syncScene();}
async function toggleListening(){if(run().complete)return;const epoch=caseEpoch;listening=!listening;const intended=listening;if(listening){await audio.init();if(epoch!==caseEpoch||listening!==intended)return;run().started=true;feedback(run().phase===0?'听诊器已接入。转动锁盘，找到最清脆的双击声。':run().phase===1?'参考音与调音已同时播放。拍频越慢，越接近共振。':'点击「聆听回响」采样，然后按顺序复现旋律。');}else{audio.stopResonance();feedback('采样已暂停。你可以继续观察或调整锁盘。');}$('#listenButton').classList.toggle('listening',listening);$('#listenButton span').textContent=listening?'暂停聆听':'开始聆听';$('#mobileListen span').textContent=listening?'暂停聆听':'开始聆听';if(listening&&run().phase===1)audio.resonance();updateSignal();save();}
function setTuning(value){const r=run();if(r.complete||r.phase>1)return;value=Math.round(Number(value));if(!Number.isFinite(value))return;if(r.phase===0)r.angle=Math.min(359,Math.max(0,value));else r.frequency=Math.min(800,Math.max(200,value));updateSignal();if(listening&&r.phase===0&&performance.now()-lastTick>60){audio.click(signal,matchesPin(r.angle,current().pins[r.pins],current().tolerance));lastTick=performance.now();}if(r.phase===1)audio.updateResonance();render();}
function fail(message){run().mistakes++;audio.error();feedback(message,'error');save();}
async function confirm(){const r=run(),c=current(),epoch=caseEpoch;if(r.complete)return;if(r.phase===2){patternInput=[];render();feedback('旋律输入已清空。可以重听后再试一次。');return;}await audio.init();if(epoch!==caseEpoch||r.complete)return;r.started=true;if(r.phase===0){if(matchesPin(r.angle,c.pins[r.pins],c.tolerance)){r.pins++;audio.success();if(r.pins===3){r.phase=1;addClue('三枚锁芯已全部嵌合','机械层解除。锁盘中心出现了一片持续振动的薄膜。');feedback('机械层已解开。调节频率，让两个声音不再起伏。','success');if(listening)audio.resonance();}else{feedback(`第 ${r.pins} 枚锁芯已嵌合。新的回响出现了，继续寻找下一枚。`,'success');toast(`锁芯 ${r.pins} / 3 已定位`);}}else fail('锁芯轻轻弹回。位置还不够准确，试着听清双击之间的余响。');}else if(matchesFrequency(r.frequency,c.frequency,c.freqTolerance)){r.phase=2;audio.stopResonance();audio.success();addClue('共振密钥已同步',`薄膜在 ${r.frequency} Hz 附近稳定下来，深处传出一段旋律。`);feedback('共振层已解开。聆听回响，再按低、中、高音复现它。','success');}else fail('两个声音仍在拍动。继续细调，直到波形与声音都平稳下来。');render();}
async function selectTool(next){tool=next;if(scene)scene.tool=next;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===next));if(next==='inspect')inspect();if(next==='knock')await knock();if(next==='listen')feedback('听诊模式：拖动锁盘，或使用下方滑杆精确定位。');}
function inspect(){feedback(current().clue);toast(current().clue);if(scene){scene.yaw=-.16;scene.pitch=.06;}$('#noteIntro').textContent=current().clue;}
async function knock(){if(run().complete)return;const epoch=caseEpoch;await audio.init();if(epoch!==caseEpoch||run().complete)return;audio.knock();const r=run();r.started=true;if(r.phase===0){const t=current().pins[Math.min(r.pins,2)];const quarter=['右上象限（0°–90°）','右下象限（90°–180°）','左下象限（180°–270°）','左上象限（270°–359°）'][Math.min(3,Math.floor(t/90))];feedback(`敲击余响指向${quarter}。在这个范围内仔细聆听。`);$('#noteIntro').textContent=`声腔探测：当前锁芯在${quarter}有更明显的应答。`;}else if(r.phase===1){audio.tone(current().frequency,1.2,'sine',.35,.3);feedback('敲击薄膜后，参考音已响起。调节频率与它匹配。');}else{feedback('箱体传回三种音色：低、中、高。先聆听完整回响。');[220,330,440].forEach((f,i)=>audio.tone(f,.24,'sine',.3,i*.3));}save();}
function useHint(){const r=run();if(r.hints>=3||r.complete)return;r.hints++;let hint=current().hints[Math.min(r.phase,2)];if(r.phase===0&&r.pins>0){const t=current().pins[r.pins];hint=`第 ${r.pins+1} 枚锁芯在 ${Math.max(0,t-12)}°–${Math.min(359,t+12)}° 之间。先大致定位，再听双击。`;}if(r.phase===2)hint+=` 顺序是：${current().pattern.map(n=>['低','中','高'][n]).join(' · ')}。`;feedback(hint);$('#noteIntro').textContent=hint;toast(hint);renderNotes();save();}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function flashNote(n){const pad=$(`[data-note="${n}"]`);pad.classList.add('pulse');setTimeout(()=>pad.classList.remove('pulse'),220);}
async function playPattern(){if(patternPlaying||run().phase!==2||run().complete)return;const epoch=caseEpoch;await audio.init();if(epoch!==caseEpoch||run().complete||patternPlaying)return;run().started=true;patternInput=[];patternPlaying=true;const token=++playToken;$('#playPattern').disabled=true;$$('[data-note]').forEach(b=>b.disabled=true);feedback('正在播放完整回响……记住音高的先后顺序。');render();for(const n of current().pattern){if(token!==playToken)return;audio.tone([220,330,440][n],.35,'sine',.45);if(settings.visualAssist)flashNote(n);await wait(current().tempo);}if(token!==playToken)return;patternPlaying=false;$('#playPattern').disabled=false;$$('[data-note]').forEach(b=>b.disabled=false);feedback('轮到你了。用 A / S / D 或音色按钮复现回响。');save();}
async function inputNote(n){if(run().phase!==2||patternPlaying||run().complete)return;const epoch=caseEpoch;await audio.init();if(epoch!==caseEpoch||run().phase!==2||run().complete||patternPlaying)return;audio.tone([220,330,440][n],.32,'sine',.45);flashNote(n);run().started=true;const expected=current().pattern[patternInput.length];if(n!==expected){fail(`第 ${patternInput.length+1} 个音与回响不符。旋律已重置，随时可以再听一次。`);patternInput=[];render();return;}patternInput.push(n);feedback(`旋律匹配 ${patternInput.length} / ${current().pattern.length}。继续聆听记忆中的下一个音。`,'success');if(patternInput.length===current().pattern.length)complete();else render();}
function complete(){const r=run();r.phase=3;r.complete=true;listening=false;audio.stopResonance();audio.success();setTimeout(()=>{[523.25,659.25,783.99,1046.5].forEach((f,i)=>audio.tone(f,1,'sine',.18,i*.16));},400);addClue('记忆回响已复现',current().story);feedback('全部机关解除。你找回了被封存的记忆。','success');$('#listenButton').classList.remove('listening');$('#listenButton span').textContent='调查完成';render();$('#unlockOverlay').hidden=true;const finishedRun=r;setTimeout(()=>{if(run()===finishedRun&&run().complete)$('#unlockOverlay').hidden=false;},1800);}
function switchCase(index){if(!Number.isInteger(index)||index<0||index>=CASES.length)return false;caseIndex=index;caseEpoch++;listening=false;patternInput=[];patternPlaying=false;playToken++;audio.stopResonance();$('#playPattern').disabled=false;$$('[data-note]').forEach(b=>b.disabled=false);$('#listenButton').classList.remove('listening');$('#listenButton span').textContent='开始聆听';$('#mobileListen span').textContent='开始聆听';scene?.setCase(index);$('#modal').close();render();feedback(run().complete?'这件藏品的秘密已被你解开。':run().phase?'已恢复这件藏品的调查进度。开启聆听，继续寻找回响。':'将听诊器贴近锁芯，开启你的第一次调查。');return true;}
function openModal(type){const modal=$('#modal');let content='';if(type==='cases'){ $('#modalEyebrow').textContent='ANOMALOUS OBJECT ARCHIVE';content='<h2>每只保险箱，都藏着一个世界。</h2><p class="modal-intro">三件来历不明的藏品，三段等待被听见的记忆。每份档案独立保存调查进度。</p>'+CASES.map((c,i)=>`<button class="case-card ${i===caseIndex?'current':''}" data-case="${i}"><strong>0${i+1}</strong><div><h3>${c.name}</h3><p>${c.origin}</p><small>${c.difficulty} · ${c.pattern.length} 音记忆</small></div><span>${runs[i].complete?'已归档 · '+rating(runs[i].mistakes,runs[i].hints):runs[i].phase>0?'调查中':i===caseIndex?'当前档案':'开始调查'}</span></button>`).join('');}else if(type==='guide'){ $('#modalEyebrow').textContent='FIELD MANUAL / EDITION 04';content='<h2>听见看不见的线索</h2><p class="modal-intro">这是异常物件调查局的虚构声学机关。无需开锁经验，也没有倒计时。错误只影响评级，不会重置已解开的机关。</p><div class="manual-step"><span>01</span><div><h3>机械锁芯 · 三次清晰的应答</h3><p>开启聆听，缓慢转动锁盘。越接近落点，单击会变成清脆的双击；观察标注也会提示距离。点击「确认落点」固定一枚锁芯，完成三枚即可继续。敲击工具可探测所在象限。</p></div></div><div class="manual-step"><span>02</span><div><h3>共振密钥 · 让两个声音合为一体</h3><p>开启聆听后，参考音与调音同时响起。频率接近时，起伏会变慢；平稳时点击「锁定共振」。你也可以敲击薄膜，单独重听参考音。</p></div></div><div class="manual-step"><span>03</span><div><h3>记忆回响 · 复现被封存的旋律</h3><p>点击「聆听回响」，记住低、中、高音的顺序，再依次点击三个音色按钮。只需顺序正确，无需抢拍。视觉辅助会同步点亮音色按钮，不影响评级。</p></div></div><div class="shortcuts"><span><kbd>SPACE</kbd> 聆听 / 暂停</span><span><kbd>← →</kbd> 精细调节</span><span><kbd>SHIFT</kbd> 加速调节</span><span><kbd>ENTER</kbd> 确认落点</span><span><kbd>1 2 3</kbd> 切换工具</span><span><kbd>A S D</kbd> 低 / 中 / 高音</span></div><p class="modal-intro" style="margin-top:22px;margin-bottom:0">每关有 3 次启发。评级依据错误确认与启发次数：累计 0–2 次为 S，3–6 次为 A，其余为 B。探索、重听与视觉辅助不会降低评级。</p>'; }else{$('#modalEyebrow').textContent='WORKBENCH SETTINGS';content='<h2>聆听偏好</h2><div class="settings-row"><div>视觉辅助<small>显示声学距离提示，并在回响播放时点亮音色。</small></div><button class="switch '+(settings.visualAssist?'on':'')+'" id="visualToggle" role="switch" aria-checked="'+settings.visualAssist+'" aria-label="视觉辅助"></button></div><div class="settings-row"><div>减少动态效果<small>停止漂浮粒子与呼吸动效。</small></div><button class="switch '+(settings.reducedMotion?'on':'')+'" id="motionToggle" role="switch" aria-checked="'+settings.reducedMotion+'" aria-label="减少动态效果"></button></div><div class="settings-row"><div>重新调查当前藏品<small>清空当前档案进度，其他档案会保留。</small></div><button class="outline-button" id="restartButton">重新开始</button></div><p class="modal-intro" style="margin-top:20px">声音由浏览器实时合成，首次点击后启用。进度保存在当前浏览器中。</p>';}$('#modalContent').innerHTML=content;icons(modal);if(!modal.open)modal.showModal();$$('[data-case]').forEach(b=>b.onclick=()=>switchCase(Number(b.dataset.case)));$('#visualToggle')?.addEventListener('click',e=>{settings.visualAssist=!settings.visualAssist;e.currentTarget.classList.toggle('on',settings.visualAssist);e.currentTarget.setAttribute('aria-checked',settings.visualAssist);updateSignal();save();});$('#motionToggle')?.addEventListener('click',e=>{settings.reducedMotion=!settings.reducedMotion;e.currentTarget.classList.toggle('on',settings.reducedMotion);e.currentTarget.setAttribute('aria-checked',settings.reducedMotion);document.body.classList.toggle('reduced-motion',settings.reducedMotion);if(scene)scene.lowMotion=settings.reducedMotion;save();});$('#restartButton')?.addEventListener('click',()=>{runs[caseIndex]=cleanRun();switchCase(caseIndex);toast('当前档案已重新开始。');});}
$('#tuning').addEventListener('input',e=>setTuning(e.target.value));$('#stepDown').onclick=()=>setTuning((run().phase===0?run().angle:run().frequency)-1);$('#stepUp').onclick=()=>setTuning((run().phase===0?run().angle:run().frequency)+1);$('#confirmButton').onclick=confirm;$('#listenButton').onclick=toggleListening;$('#mobileListen').onclick=toggleListening;$('#viewArtifact').onclick=()=>{$('#unlockOverlay').hidden=true;$('#returnReport').hidden=false;scene?.resetView();};$('#returnReport').onclick=()=>{$('#unlockOverlay').hidden=false;$('#returnReport').hidden=true;};$('#gain').oninput=e=>{gain=Number(e.target.value)/100;$('#gainValue').textContent=`${Math.round(gain*100)}%`;e.target.style.setProperty('--value',`${gain*100}%`);audio.volume();updateSignal();};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(el=>el.classList.toggle('selected',el===b));toast(filter==='raw'?'原始信号：保留锁芯的完整音色。':filter==='low'?'低频滤波：突出箱体的低沉共鸣。':'高频滤波：突出锁芯清脆的金属应答。');});$('#filterHelp').onclick=()=>toast('原始保留完整音色；低频突出箱体共鸣，高频突出锁芯双击。共振阶段保留纯音以便判断拍频。');$$('[data-tool]').forEach(b=>b.onclick=()=>selectTool(b.dataset.tool));$('#resetView').onclick=()=>{scene?.resetView();$('.scene-panel').classList.remove('focused');toast('观察视角已复位。');};$('#focusButton').onclick=()=>{scene?.focus();$('.scene-panel').classList.toggle('focused');};$('#fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.scene-panel').requestFullscreen();}catch{toast('当前浏览器不支持全屏。可以用滚轮放大保险箱。');}};$('#hintButton').onclick=useHint;$('#playPattern').onclick=playPattern;$$('[data-note]').forEach(b=>b.onclick=()=>inputNote(Number(b.dataset.note)));$('#caseSelect').onclick=()=>openModal('cases');$$('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='game'){$('#modal').close();return;}openModal(b.dataset.nav);});$('#shortcutButton').onclick=()=>openModal('guide');$('#settingsButton').onclick=()=>openModal('settings');$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});$('#nextCase').onclick=()=>caseIndex<2?switchCase(caseIndex+1):openModal('cases');$('#muteButton').onclick=()=>{settings.muted=!settings.muted;audio.volume();$('#muteButton i').dataset.icon=settings.muted?'muted':'volume';icons($('#muteButton'));$('#muteButton').setAttribute('aria-label',settings.muted?'取消静音':'静音');toast(settings.muted?'声音已静音，视觉辅助仍然可用。':'声音已恢复。');save();};
document.addEventListener('keydown',e=>{if($('#modal').open||e.target.matches('textarea, input:not([type=range])'))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)toggleListening();}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(e.target.matches('input[type=range]'))return;e.preventDefault();const delta=(e.key==='ArrowRight'?1:-1)*(e.shiftKey?10:1);setTuning((run().phase===0?run().angle:run().frequency)+delta);}else if(e.key==='Enter'&&!e.target.closest('button')){e.preventDefault();confirm();}else if(['1','2','3'].includes(e.key))selectTool(['listen','inspect','knock'][Number(e.key)-1]);else if(['a','s','d'].includes(e.key.toLowerCase())&&!e.repeat)inputNote(['a','s','d'].indexOf(e.key.toLowerCase()));else if(e.key==='?')openModal('guide');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){audio.ctx?.suspend();if(patternPlaying){playToken++;patternPlaying=false;patternInput=[];$('#playPattern').disabled=false;$$('[data-note]').forEach(b=>b.disabled=false);render();feedback('回响示范因页面切换而暂停。返回后可重新聆听完整旋律。');}}else if(audio.ctx&&listening){audio.ctx.resume().catch(()=>{});}});
setInterval(()=>{if(run().started&&!run().complete&&!document.hidden&&!$('#modal').open){run().seconds++;$('#timer').textContent=time(run().seconds);if(run().seconds%5===0)save();}if(listening&&run().phase===0&&!document.hidden)audio.click(signal,matchesPin(run().angle,current().pins[run().pins],current().tolerance));},1000);
const canvas=$('#waveform'),ctx=canvas.getContext('2d');function drawWave(){requestAnimationFrame(drawWave);const w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(w*d)||canvas.height!==Math.round(h*d)){canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);}ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#243623';ctx.lineWidth=.5;for(let x=0;x<w;x+=w/10){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=0;y<h;y+=h/6){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}const t=settings.reducedMotion?0:performance.now()*.002;ctx.strokeStyle=listening?'#b7bf89':'#718062';ctx.lineWidth=listening?1.15:.8;ctx.shadowColor='#b9cb76';ctx.shadowBlur=listening?5:0;ctx.beginPath();let useAudio=listening&&audio.ctx?.state==='running'&&!settings.muted;if(useAudio)audio.analyser.getByteTimeDomainData(audio.data);for(let x=0;x<w;x++){let y=h*.49;if(useAudio)y+=(audio.data[Math.floor(x/w*audio.data.length)]-128)/128*h*.7;else if(listening){const amp=(.12+signal*.5)*h*.35;const beat=run().phase===1?.4+.6*Math.abs(Math.sin(x*.004*Math.max(1,Math.abs(run().frequency-current().frequency))*.06+t)):Math.exp(-Math.pow((x/w-.5)*4,2));y+=Math.sin(x*.21+t*4)*amp*beat+Math.sin(x*.59+t)*amp*.22;}else y+=Math.sin(x*.13)*.65; if(x===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();ctx.shadowBlur=0;}
drawWave();document.body.classList.toggle('reduced-motion',settings.reducedMotion);$('#muteButton i').dataset.icon=settings.muted?'muted':'volume';icons($('#muteButton'));render();
if(run().phase>0&&!run().complete)feedback('已恢复你的调查进度。开始聆听，继续解开这只保险箱。');
