if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_vault_progress',description:'Read current visible game progress without revealing solutions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({caseIndex,caseName:current().name,phase:run().phase,pins:run().pins,angle:run().angle,frequency:run().frequency,complete:run().complete,clues:run().clues})});register({name:'start_vault_case',description:'Select a case and restore its saved progress.',inputSchema:{type:'object',properties:{caseIndex:{type:'integer',minimum:0,maximum:2}},required:['caseIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.caseIndex)||!switchCase(input.caseIndex))throw new Error('caseIndex must be 0, 1, or 2');return{caseName:current().name,phase:run().phase};}});register({name:'adjust_vault_tuning',description:'Adjust the visible dial angle or frequency during the corresponding stage; does not confirm a solution.',inputSchema:{type:'object',properties:{value:{type:'integer',minimum:0,maximum:800}},required:['value'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.value)||run().phase>1||run().complete||input.value<(run().phase===0?0:200)||input.value>(run().phase===0?359:800))throw new Error('Invalid tuning value for the current phase');setTuning(input.value);return{value:run().phase===0?run().angle:run().frequency,phase:run().phase};}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
